const state={page:'home',selected:'Code',feedFilter:'All activity',feedExpanded:false,feedDropdown:false,completed:new Set(JSON.parse(localStorage.getItem('ghg-completed')||'[]')),search:'',dictFilter:'全部',repoTab:'Code',branch:'main',branches:['main'],files:[{name:'README.md',message:'Update README',time:'yesterday',content:'# Hello, GitHub!\n\nThis is a safe practice repository.\nUse the tabs above to explore.'},{name:'LICENSE',message:'Add license',time:'last week',content:'MIT License\n\nPermission is hereby granted...'}, {name:'src/',message:'Add starter files',time:'last week',content:'This folder contains the project source files.'}],fileOpen:'',codeOpen:false,cloneType:'HTTPS',queryFile:'',issueOpen:false,issues:[{id:2,title:'Add a clear project description',label:'documentation',open:true},{id:1,title:'Fix the typo in the welcome message',label:'good first issue',open:true}],issueFilter:'open',issueDetail:null,issueComposer:false,prOpen:false,prMerged:false,prDetail:false,prComposer:false,starred:false,watching:false,forked:false,actions:0,logs:false,projectView:'Board',cards:[{title:'Review navigation',status:'Todo'},{title:'Build the learning homepage',status:'In Progress'},{title:'Choose a project name',status:'Done'}],orgTab:'Overview',settingsTab:'General',profileTab:'Overview',profileEditing:false,packageType:'All',packageDetail:'',settingsName:'hello-world',issueAssigned:false,issueCommenting:false,issueComments:[],fileEditing:false};
const main=document.querySelector('#main'),toastEl=document.querySelector('#toast');let toastTimer;
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2200)}
function complete(id){if(!id)return;state.completed.add(id);localStorage.setItem('ghg-completed',JSON.stringify([...state.completed]));updateProgress()}
function updateProgress(){let n=Object.keys(pageInfo).length+2,p=Math.round(state.completed.size/n*100);document.querySelector('#progress-text').textContent=p+'%';document.querySelector('#progress-bar').style.width=p+'%'}
function nav(id){window.dispatchEvent(new CustomEvent('legacy-page',{detail:id}));state.page=id;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===id||b.dataset.action===id));render();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}
function term(w){return `<button class="term" type="button" data-explain="${esc(w)}">${esc(w)}</button>`}
function simTop(){return `<div class="sim-banner">演示界面 · 所有操作仅改变本站示例，不连接或修改真实 GitHub。</div><div class="sim-top"><span class="sim-logo">●</span><b>GitHub</b><button class="sim-search hotspot" data-action="global-search">⌕　Search or jump to...</button><button class="icon-btn hotspot" data-explain="Notifications" aria-label="Notifications">♧</button><span class="avatar">学</span></div>`}
const tabs=['Code','Issues','Pull requests','Actions','Projects','Wiki','Security','Insights','Settings'];
function tabNav(t){const map={Code:'repo',Issues:'issues','Pull requests':'pulls',Actions:'actions',Projects:'projects',Settings:'settings'};if(map[t]){nav(map[t]);return}state.repoTab=t;render();explain(t);}
function simTabs(active,items=tabs){return `<div class="sim-tabs">${items.map(t=>`<button class="sim-tab ${active===t?'selected':''} hotspot" data-action="tab" data-value="${esc(t)}">${t}${t==='Issues'?` ${state.issues.filter(x=>x.open).length}`:t==='Pull requests'?(state.prMerged?'0':'1'):''}</button>`).join('')}</div>`}
function btn(label,action,cls=''){return `<button class="button ${cls}" data-action="${action}">${label}</button>`}
function explainBtn(label){return `<button class="button subtle hotspot" data-explain="${esc(label)}">${label}</button>`}
function pageHeader(id){const p=pageInfo[id];return `<div class="content-header"><div class="eyebrow">${p[1]}</div><h1>${p[0]}</h1><p>${p[2]}</p></div>`}
function sideExplain(){return `<section class="panel explain-card" id="explain-panel"><div class="panel-title">英文解释 <small>点击英文控件查看</small></div><div class="panel-body" id="explain-content"><h3 class="explain-word">${esc(state.selected)}</h3><div class="explain-meaning">选择一个英文按钮或页面区域</div><p class="explain-copy">这里会显示它的中文含义、用途和常见场景。</p></div></section>`}
function lesson(id){let samples={overview:[['GitHub','在线项目协作平台','可以浏览项目、保存自己的项目并与他人协作。'],['Git','记录文件变化的工具','Git 追踪修改；GitHub 提供在线托管和协作界面。'],['Repository','项目仓库','像一个带历史记录的项目文件夹。'],['Commit','一次存档','记录一组修改以及修改说明。']],profile:[['Overview','个人主页概览','显示简介、置顶仓库、贡献活动。'],['Repositories','仓库列表','查看你创建或参与的项目。'],['Pinned','置顶项目','把常用仓库展示在个人主页。'],['Edit profile','编辑资料','修改头像、简介和主页信息。']],repo:[['Code','项目文件','浏览仓库文件、查看说明或获取克隆地址。'],['Add file','添加文件','在仓库中创建文件或上传文件。'],['Go to file','查找文件','按文件名快速定位仓库中的文件。'],['History','修改历史','查看过去的提交以及改动。']],issues:[['New issue','新建任务','写下问题、建议或待处理事项。'],['Labels','标签','给任务分类并方便筛选。'],['Assignees','负责人','指定由谁跟进处理。'],['Milestones','里程碑','把相关任务归入一个阶段或版本。']],pulls:[['Compare changes','比较修改','查看来源分支与目标分支之间的差异。'],['Reviewers','审查者','邀请他人检查修改并反馈。'],['Files changed','改动文件','查看提案具体修改了哪些内容。'],['Merge pull request','合并提案','把审查通过的改动合入目标分支。']]};let rows=samples[id]||[['Overview','概览','查看此功能区的主要信息。'],['Settings','设置','管理相关配置，具体权限因账号角色而异。'],['Activity','活动记录','查看近期操作或运行状态。'],['Help','帮助','了解该功能的操作方法。']];return `${pageHeader(id)}<div class="lesson-grid"><section class="panel"><div class="panel-title">常见英文 <small>点击英文看中文释义</small></div><div class="panel-body"><ol class="guide-list">${rows.map((r,i)=>`<li><span class="step-num">${i+1}</span><div><b>${term(r[0])} — ${r[1]}</b><p>${r[2]}</p></div></li>`).join('')}</ol><div class="note">以下是可操作的界面模拟。页面按钮会产生站内演示结果，不会访问真实 GitHub。</div></div></section>${sideExplain()}</div>${simulator(id)}`}
function repoPage(){let visible=state.files.filter(f=>f.name.toLowerCase().includes(state.queryFile.toLowerCase()));let fileView=state.fileOpen?`<div class="file-open-head"><button class="button subtle" data-action="back-files">← Go to files</button><b>${esc(state.fileOpen)}</b><button class="button subtle" data-action="edit-file">Edit</button></div><pre class="file-preview">${esc(state.files.find(f=>f.name===state.fileOpen)?.content||'This is a demo file.')}</pre>`:`<div class="sim-toolbar"><button class="branch-select" data-action="branch-menu">⑂ ${esc(state.branch)} ▾</button><button class="branch-select" data-action="goto-file">Go to file</button><span class="spacer"></span><button class="button subtle" data-action="add-file">Add file ▾</button><button class="button primary" data-action="code-menu">Code ▾</button></div>${state.codeOpen?`<div class="dropdown-panel"><b>Clone</b><div class="filter-row">${['HTTPS','SSH','GitHub CLI'].map(t=>`<button class="filter-chip ${state.cloneType===t?'active':''}" data-action="clone-type" data-value="${t}">${t}</button>`).join('')}</div><div class="clone-url"><code>${state.cloneType==='HTTPS'?'https://github.com/octocat/hello-world.git':state.cloneType==='SSH'?'git@github.com:octocat/hello-world.git':'gh repo clone octocat/hello-world'}</code><button class="button" data-action="copy-clone">Copy</button></div><small>复制地址后可在 GitHub Desktop 中克隆此示例仓库。</small></div>`:''}${state.fileMenu?`<div class="dropdown-panel menu-panel"><button data-action="create-file">Create new file</button><label class="menu-upload">Upload files<input type="file" id="upload-file" hidden></label></div>`:''}${state.branchMenu?`<div class="dropdown-panel menu-panel"><b>Switch branches/tags</b><input class="inline-input" id="branch-name" placeholder="Find or create a branch…"><div>${state.branches.map(b=>`<button data-action="switch-branch" data-value="${esc(b)}">${state.branch===b?'✓ ':''}${esc(b)}</button>`).join('')}</div><button data-action="create-branch">＋ Create branch from ${esc(state.branch)}</button></div>`:''}${state.fileComposer?`<div class="dropdown-panel"><b>Create a new file</b><input class="inline-input" id="new-filename" placeholder="Name your file…"><textarea class="inline-input" id="new-filecontent" placeholder="Write your file contents…"></textarea><button class="button primary" data-action="save-file">Commit changes</button><button class="button" data-action="cancel-file">Cancel</button></div>`:''}${state.gotoOpen?`<div class="dropdown-panel"><input class="inline-input" id="file-search" placeholder="Type to search files…" value="${esc(state.queryFile)}"><button data-action="close-goto">Close</button></div>`:''}<div class="file-list">${visible.map(f=>`<div class="file-row"><button class="file-link" data-action="open-file" data-value="${esc(f.name)}">${esc(f.name)}</button><span>${esc(f.message)}</span><span>${f.time}</span></div>`).join('')||'<div class="empty">No files match your search.</div>'}</div><div class="readme"><h3>▤　README.md <button class="button subtle" data-action="edit-readme">Edit</button></h3><p># Hello, GitHub!<br>This is a safe practice repository.<br>Use the tabs above to explore.</p></div>`;
return `<div class="sim-repo-head"><div class="crumb"><button class="text-link" data-action="repo-owner">octocat</button> / <b>hello-world</b><span class="visibility">Public</span></div><p class="repo-description">A friendly place to practice GitHub</p><div class="repo-actions"><button class="button" data-action="watch">${state.watching?'Unwatch':'Watch'}　${state.watching?'1':'0'} ▾</button><button class="button" data-action="fork">${state.forked?'Forked':'Fork'}　${state.forked?'1':'0'}</button><button class="button" data-action="star">${state.starred?'★ Starred':'☆ Star'}　${state.starred?'25':'24'}</button></div></div>${simTabs(state.repoTab)}<div class="sim-content">${state.repoTab==='Code'?fileView:`<div class="sim-toolbar"><b>${esc(state.repoTab)}</b><span class="spacer"></span>${explainBtn('About this section')}</div><div class="feature-panel"><h3>${esc(state.repoTab)}</h3><p>${sectionDescription(state.repoTab)}</p>${state.repoTab==='Wiki'?'<button class="button" data-action="wiki-edit">Create the first page</button>':''}${state.repoTab==='Security'?'<button class="button" data-action="security-check">View security overview</button>':''}${state.repoTab==='Insights'?'<button class="button" data-action="insights-view">View traffic</button>':''}</div>`}</div><aside class="repo-about"><b>About</b><p>A friendly place to practice GitHub</p><button class="text-link" data-action="topics">Add a description, website, and topics</button><hr><p>⭐ ${state.starred?'25':'24'}　⑂ 3 forks</p><button class="text-link" data-action="releases">Releases　<span>1</span></button><button class="text-link" data-action="packages-nav">Packages</button><button class="text-link" data-action="contributors">Contributors　3</button></aside>`}
function sectionDescription(t){return ({Wiki:'Wiki 是项目文档区，可以添加多页说明。',Security:'查看安全策略、漏洞报告和安全建议。',Insights:'了解项目的贡献、流量和活动情况。'})[t]||'浏览这个项目功能区的演示内容。'}
function issuePage(){let list=state.issues.filter(i=>state.issueFilter==='all'||(state.issueFilter==='open'?i.open:!i.open));return `<div class="sim-repo-head"><div class="crumb">octocat / <b>hello-world</b></div><p class="repo-description">Issues help track ideas, feedback, tasks, or bugs.</p></div>${simTabs('Issues')}<div class="sim-content">${state.issueComposer?`<div class="form-panel"><h3>New issue</h3><label>Title <input class="inline-input" id="issue-title" placeholder="Add a clear title"></label><label>Description <textarea class="inline-input" id="issue-body" placeholder="Describe the issue…"></textarea></label><button class="button primary" data-action="save-issue">Submit new issue</button><button class="button" data-action="cancel-issue">Cancel</button></div>`:state.issueDetail!==null?issueDetail():`<div class="sim-toolbar"><button class="filter-chip ${state.issueFilter==='open'?'active':''}" data-action="issue-filter" data-value="open">${thisCount(true)} Open</button><button class="filter-chip ${state.issueFilter==='closed'?'active':''}" data-action="issue-filter" data-value="closed">${thisCount(false)} Closed</button><span class="spacer"></span><button class="button subtle" data-action="label-menu">Labels ▾</button><button class="button subtle" data-action="milestone-menu">Milestones ▾</button><button class="button primary" data-action="new-issue">New issue</button></div>${state.labelMenu?`<div class="dropdown-panel menu-panel">${['bug','documentation','enhancement','good first issue'].map(x=>`<button data-action="filter-label" data-value="${x}">${x}</button>`).join('')}</div>`:''}${state.milestoneMenu?'<div class="dropdown-panel">No milestones are open. <button data-action="milestone-create">Create a milestone</button></div>':''}<div class="file-list">${list.map(i=>`<button class="issue-list-row" data-action="issue-detail" data-value="${i.id}"><span class="issue-dot">${i.open?'●':'✓'}</span><span><b>${esc(i.title)}</b><small>#${i.id} opened recently by octocat · ${esc(i.label)}</small></span></button>`).join('')||'<div class="empty">No issues found.</div>'}</div>`}</div>`}
function thisCount(open){return state.issues.filter(i=>i.open===open).length}
function issueDetail(){let i=state.issues.find(x=>x.id===state.issueDetail);if(!i)return '';return `<div class="detail-toolbar"><button class="button" data-action="issue-back">← Issues</button><span class="spacer"></span><button class="button" data-action="toggle-issue">${i.open?'Close issue':'Reopen issue'}</button></div><div class="detail-card"><h2>${esc(i.title)} <small>#${i.id}</small></h2><span class="tag">${i.open?'Open':'Closed'}</span> <span>octocat opened this issue</span><hr><p>This is a safe, simulated issue detail page. Use the close button to change its state.</p><button class="filter-chip">${esc(i.label)}</button><button class="button" data-action="assign-issue">${state.issueAssigned?'Unassign yourself':'Assignees'}</button><hr>${state.issueComments.map(c=>`<p class="comment-entry">${esc(c)}</p>`).join('')}${state.issueCommenting?`<textarea class="inline-input" id="issue-comment" placeholder="Leave a comment…"></textarea><button class="button primary" data-action="post-comment">Comment</button><button class="button" data-action="cancel-comment">Cancel</button>`:`<button class="button" data-action="comment-issue">Comment</button>`}</div>`}
function pullsPage(){return `<div class="sim-repo-head"><div class="crumb">octocat / <b>hello-world</b></div><p class="repo-description">Propose, review, and merge changes.</p></div>${simTabs('Pull requests')}<div class="sim-content">${state.prComposer?`<div class="form-panel"><h3>Compare changes</h3><div class="branch-pair"><label>base: <select id="pr-base"><option>main</option></select></label><span>←</span><label>compare: <select id="pr-compare"><option>improve-readme</option>${state.branches.map(b=>`<option>${esc(b)}</option>`).join('')}</select></label></div><label>Title <input class="inline-input" id="pr-title" value="Practice: improve README"></label><label>Description <textarea class="inline-input" id="pr-body">Describe your proposed changes.</textarea></label><button class="button primary" data-action="save-pr">Create pull request</button><button class="button" data-action="cancel-pr">Cancel</button></div>`:state.prDetail?`<div class="detail-toolbar"><button class="button" data-action="pr-back">← Pull requests</button><span class="spacer"></span>${state.prMerged?'<span class="tag">Merged</span>':`<button class="button" data-action="close-pr">Close pull request</button><button class="button primary" data-action="merge-pr">Merge pull request</button>`}</div><div class="detail-card"><h2>${esc(state.prTitle||'Practice: improve README')} <small>#1</small></h2><span class="tag">${state.prMerged?'Merged':'Open'}</span> <span>learner wants to merge 1 commit into main</span>${simTabs(state.prTab||'Conversation',['Conversation','Commits','Files changed'])}<div class="panel-body"><p>${state.prTab==='Files changed'?'README.md　+2 −0':state.prTab==='Commits'?'Update README · 1 commit':'This demo pull request proposes a small README improvement.'}</p>${state.prMerged?'This change has been merged.':'Checks passed · No conflicts with the base branch.'}</div></div>`:`<div class="sim-toolbar"><button class="filter-chip active">${state.prMerged?'0':'1'} Open</button><button class="filter-chip">${state.prMerged?'1':'0'} Closed</button><span class="spacer"></span>${explainBtn('Filters')}<button class="button primary" data-action="new-pr">New pull request</button></div><div class="file-list"><button class="issue-list-row" data-action="pr-detail"><span class="issue-dot">${state.prMerged?'✓':'⇄'}</span><span><b>${esc(state.prTitle||'Practice: improve README')}</b><small>#1 learner wants to merge 1 commit into main from improve-readme · ${state.prMerged?'merged':'opened'}</small></span></button></div>`}</div>`}
function simulator(id){let body=id==='repo'?repoPage():id==='issues'?issuePage():id==='pulls'?pullsPage():otherSim(id);return `<section class="panel sim-panel" style="margin-top:20px"><div class="panel-title">GitHub 界面模拟 <small>控件可交互 · 内容仅为演示</small></div>${simTop()}${body}</section>`}
function otherSim(id){if(id==='overview')return `<div class="sim-content"><div class="overview-intro"><h1>GitHub</h1><p>Where the world builds software</p><p>Build, share, and collaborate on projects with people around the world.</p></div><div class="cards"><button class="card" data-action="open-repo"><h3>Repositories</h3><p>Browse code and project files</p></button><button class="card" data-action="explore"><h3>Explore</h3><p>Discover public projects</p></button><button class="card" data-action="open-profile"><h3>People</h3><p>Visit a developer profile</p></button></div></div>`;if(id==='profile')return `<div class="sim-content"><div class="profile-card"><div class="profile-cover"></div><div class="profile-info"><div class="profile-avatar">🐙</div>${state.profileEditing?`<label>Name<input class="inline-input" id="profile-name" value="octocat"></label><label>Bio<textarea class="inline-input" id="profile-bio">Learning GitHub one click at a time</textarea></label><button class="button primary" data-action="profile-save">Save</button><button class="button" data-action="profile-cancel">Cancel</button>`:`<h3>octocat</h3><p>The Octocat · Learning GitHub one click at a time</p><button class="button" data-action="profile-edit">Edit profile</button>`}<div class="profile-stats"><span><b>12</b> followers</span><span><b>8</b> following</span></div></div>${simTabs(state.profileTab,['Overview','Repositories','Projects','Packages'])}<div class="panel-body"><b>${esc(state.profileTab==='Overview'?'Popular repositories':state.profileTab)}</b><div class="file-row"><button class="file-link" data-action="open-repo">hello-world</button><span>Practice repo</span><span>★ 24</span></div></div></div></div>`;
if(id==='projects')return `<div class="sim-content"><div class="sim-toolbar"><b>Website launch</b><span class="spacer"></span><button class="filter-chip ${state.projectView==='Board'?'active':''}" data-action="project-view" data-value="Board">Board</button><button class="filter-chip ${state.projectView==='Table'?'active':''}" data-action="project-view" data-value="Table">Table</button><button class="button primary" data-action="add-card">＋ Add item</button></div>${state.projectView==='Board'?`<div class="board">${['Todo','In Progress','Done'].map(st=>`<div class="board-col"><h4>${st} · ${state.cards.filter(c=>c.status===st).length}</h4>${state.cards.filter(c=>c.status===st).map((c,i)=>`<div class="board-card"><button class="card-title" data-action="card-detail" data-value="${esc(c.title)}">${esc(c.title)}</button><select aria-label="Move card" data-action="move-card" data-value="${esc(c.title)}">${['Todo','In Progress','Done'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</div>`).join('')}</div>`:`<div class="file-list">${state.cards.map(c=>`<div class="file-row"><b>${esc(c.title)}</b><span>${c.status}</span><select data-action="move-card" data-value="${esc(c.title)}">${['Todo','In Progress','Done'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</div>`}${state.cardComposer?`<div class="form-panel"><input class="inline-input" id="card-title" placeholder="Item title"><button class="button primary" data-action="save-card">Add item</button><button class="button" data-action="cancel-card">Cancel</button></div>`:''}</div>`;
if(id==='actions')return `<div class="sim-content"><div class="sim-toolbar"><b>All workflows</b><span class="spacer"></span><button class="button primary" data-action="run-workflow">Run workflow</button></div><div class="file-list">${['CI','Deploy website'].map((w,i)=>`<div class="issue-row"><span class="issue-dot">${state.actions?'✓':'◉'}</span><span><b>${w}</b><small>${state.actions?'Success · completed just now':'Waiting for a run · main branch'}</small></span><button class="button" data-action="workflow-logs" data-value="${w}">Logs</button></div>`).join('')}</div>${state.logs?`<div class="detail-card"><b>Workflow run #${state.actions||1} · ${state.logs}</b><pre class="file-preview">✓ Set up job\n✓ Checkout repository\n✓ Run checks\n✓ Complete job\nProcess completed with exit code 0</pre><button class="button" data-action="close-logs">Close logs</button></div>`:''}<div class="note">运行按钮只更新演示状态，不会执行真实构建或发布。</div></div>`;
if(id==='packages')return `<div class="sim-content"><div class="sim-toolbar"><b>Packages</b><span class="spacer"></span><select class="branch-select" data-action="package-filter"><option>All</option><option>Container</option><option>npm</option></select></div><div class="file-list">${[['hello-world','Container','2 days ago'],['design-tokens','npm','last week']].filter(x=>state.packageType==='All'||x[1]===state.packageType).map(x=>`<div class="issue-row"><span>⬡</span><span><b>octocat / ${x[0]}</b><small>${x[1]} · Updated ${x[2]} · Public</small></span><button class="button" data-action="package-detail" data-value="${x[0]}">Versions</button><button class="button" data-action="package-install" data-value="${x[0]}">Install</button></div>`).join('')}</div>${state.packageDetail?`<div class="detail-card"><h3>${esc(state.packageDetail)}</h3><p>${state.packageDetail.startsWith('Install')?'Install command copied in this demo: npm install @octocat/design-tokens':'Versions: v1.2.0 · v1.1.0 · v1.0.0'}</p><button class="button" data-action="package-close">Close</button></div>`:''}</div>`;
if(id==='org')return `<div class="sim-repo-head"><div class="crumb">◉ <b>octo-team</b><span class="visibility">Organization</span></div><p class="repo-description">A friendly team learning together</p></div>${simTabs(state.orgTab,['Overview','Repositories','People','Teams','Projects','Packages','Settings'])}<div class="panel-body"><h3>${esc(state.orgTab)}</h3><div class="cards"><button class="card" data-action="org-detail" data-value="design-team"><h3>design-team</h3><p>4 members · 3 repositories</p></button><button class="card" data-action="org-detail" data-value="Repositories"><h3>Repositories</h3><p>Shared projects owned by octo-team</p></button></div>${state.orgDetail?`<div class="detail-card">${esc(state.orgDetail)}<p>Organization page content for this section.</p><button class="button" data-action="org-clear">Close</button></div>`:''}</div>`;
return `<div class="sim-repo-head"><div class="crumb">octocat / <b>hello-world</b></div></div>${simTabs(state.settingsTab,['General','Access','Branches','Actions','Webhooks','Danger Zone'])}<div class="panel-body"><h3>${esc(state.settingsTab)} settings</h3>${state.settingsTab==='General'?`<div class="file-list"><div class="issue-row"><span><b>Repository name</b><small>${esc(state.settingsName)}</small></span><button class="button" data-action="rename">Rename</button></div><div class="issue-row"><span><b>Features</b><small>Issues, discussions, and projects</small></span><button class="button" data-action="features">Manage</button></div></div>`:`<div class="feature-panel"><p>${settingsDescription(state.settingsTab)}</p><button class="button" data-action="settings-detail">${state.settingsTab==='Danger Zone'?'Review options':'Configure '+state.settingsTab}</button></div>`}${state.settingsForm?`<div class="form-panel"><label>New repository name<input class="inline-input" id="repo-name" value="${esc(state.settingsName)}"></label><button class="button primary" data-action="save-rename">Save changes</button><button class="button" data-action="cancel-rename">Cancel</button></div>`:''}${state.featurePanel?`<div class="detail-card">${esc(state.featurePanel)}<p>This is a demo setting. No actual repository configuration will change.</p><button class="button" data-action="close-feature">Close</button></div>`:''}</div>`}
function settingsDescription(t){return ({Access:'Manage collaborators and repository access.',Branches:'Set default branches and branch protection rules.',Actions:'Control workflow permissions and automation settings.',Webhooks:'Configure integrations that receive repository events.','Danger Zone':'Transfer or delete repository actions can have significant effects. Review carefully.'})[t]||'Settings for this repository.'}
function repoLayout(){return `<div class="repo-layout"><div>${repoPage()}</div></div>`}
function render(){if(state.page==='home'){home();return}if(state.page==='explore'){explore();annotateButtons?.();return}if(state.page==='feed'){feedPage();annotateButtons?.();return}if(state.page==='dictionary'){dictionary();return}if(state.page==='quiz'){quiz();return}if(pageInfo[state.page]){main.innerHTML=simulator(state.page);annotateButtons?.();return}home()}
function home(){main.innerHTML=`<div class="gh-home"><div class="gh-welcome"><div><div class="eyebrow">MONDAY, OCTOBER 28</div><h1>Good morning, octocat</h1><p>Here’s what’s happening across your GitHub.</p></div><button class="button" data-action="home-customize">Customize your dashboard</button></div><div class="gh-dashboard"><section><div class="gh-box"><div class="gh-box-title"><b>🏠 Home</b><button class="text-link" data-action="feed-filter">Filter</button></div><div class="gh-feed-item"><span class="feed-avatar">🐙</span><div><b>octocat</b> pushed to <button class="text-link" data-action="open-repo">hello-world</button><small>2 commits · 2 hours ago</small><div class="feed-commit">Improve README and add project setup instructions</div></div></div><div class="gh-feed-item"><span class="feed-avatar">👩</span><div><b>octocat</b> opened a pull request in <button class="text-link" data-action="open-repo">world-simulator</button><small>#18 · yesterday</small><div class="feed-commit">Add interactive map view</div></div></div><div class="gh-feed-item"><span class="feed-avatar">🧑</span><div><b>octo-team</b> created a project<br><small>Website refresh · 3 days ago</small></div></div><button class="button subtle" data-action="feed-more">Show more activity</button></div><div class="gh-box"><div class="gh-box-title"><b>Top repositories</b><button class="text-link" data-action="repo-new">New</button></div>${[['hello-world','A friendly place to practice GitHub','JavaScript'],['world-simulator','Explore a tiny interactive world','TypeScript'],['design-system','Reusable components for the team','CSS']].map(x=>`<button class="gh-repo-row" data-action="open-repo"><span class="repo-icon">▤</span><span><b>octocat / ${x[0]}</b><small>${x[1]}</small><small>● ${x[2]}</small></span><span class="tag">Public</span></button>`).join('')}<button class="button subtle" data-action="all-repos">Show all repositories</button></div></section><aside><div class="gh-box"><div class="gh-box-title"><b>Explore repositories</b><button class="text-link" data-action="explore">Explore</button></div>${[['freeCodeCamp/freeCodeCamp','Learn to code for free'],['microsoft/vscode','Code editing. Redefined.'],['vercel/next.js','The React Framework']].map(x=>`<button class="suggestion" data-action="open-repo"><b>${x[0]}</b><small>${x[1]}</small><span>☆ Star　<span class="text-link">View repository</span></span></button>`).join('')}</div><div class="gh-box"><div class="gh-box-title"><b>Latest changes</b><span class="tag">Demo</span></div><p class="muted-copy">This page uses illustrative activity so you can learn the layout safely.</p><button class="text-link" data-action="learn">How this page works →</button></div></aside></div></div>`}
function feedPage(){const posts=[{user:'octocat',verb:'published 2 releases',title:'v2.8.3 — Community preview is here',body:'A new release is available. Read the release notes and explore what changed in this project.',repo:'octocat/hello-world',time:'1 hour ago',kind:'release'},{user:'github-learning',verb:'opened a pull request',title:'Add a beginner-friendly walkthrough',body:'This proposal adds step-by-step guidance for first-time contributors.',repo:'github-learning/guide',time:'Yesterday',kind:'pull'},{user:'octo-team',verb:'created a repository',title:'practice-lab',body:'A safe place to learn GitHub workflows and explore sample projects.',repo:'octo-team/practice-lab',time:'2 days ago',kind:'repository'}].filter(p=>state.feedFilter==='All activity'||state.feedFilter===p.kind);main.innerHTML=`<div class="feed-layout"><section class="feed-column"><div class="feed-heading"><h1>Feed</h1><button class="button" data-action="feed-filter-toggle">☷　Filter</button></div>${state.feedDropdown?`<div class="dropdown-panel feed-filter-menu">${[['All activity','All activity'],['Releases','release'],['Pull requests','pull'],['Repositories','repository']].map(x=>`<button class="menu-choice" data-action="feed-filter-set" data-value="${x[1]}">${state.feedFilter===x[1]?'✓ ':''}${x[0]}</button>`).join('')}</div>`:''}<div class="feed-cards">${posts.map((p,i)=>`<article class="feed-post"><div class="feed-post-meta"><span class="feed-avatar">${p.user==='octocat'?'🐙':'◉'}</span><div><b>${p.user}</b> ${p.verb} · <button class="text-link" data-action="search-open-repo">${p.repo}</button><small>${p.time}</small></div><button class="dots-button" data-action="feed-post-menu" aria-label="More options">···</button></div><h2>${p.title}</h2><div class="feed-preview"><h3>${p.kind==='release'?'Release notes':p.kind==='pull'?'Pull request':'Repository'}</h3><p>${p.body}</p><button class="text-link" data-action="search-open-repo">Read more</button></div><div class="feed-post-actions"><button class="reaction-button" data-action="feed-react">${state.feedReacted?'☺ Liked':'☺'}</button><span>${state.feedReacted?'You reacted':' '}</span></div></article>`).join('')||'<div class="empty">No activity matches this filter.</div>'}${state.feedExpanded?`<article class="feed-post"><b>octocat</b> starred a repository · <small>3 days ago</small><p>Explore projects from the community.</p></article>`:''}<button class="button" data-action="feed-expand">${state.feedExpanded?'Show fewer':'Show more activity'}</button></div></section><aside class="feed-aside"><div class="gh-box"><div class="gh-box-title"><b>GitHub Universe ’26</b><button class="dots-button" data-action="dismiss-banner">×</button></div><p>Catch up on the latest announcements.</p><button class="button blue" data-action="learn">See what’s new</button></div><div class="gh-box"><div class="gh-box-title"><b>Latest from our changelog</b></div><p>Copilot code review updates</p><p>Improvements to project workflows</p><button class="text-link" data-action="learn">Read the changelog</button></div></aside></div>`}
function explore(){const projects=[['freeCodeCamp/freeCodeCamp','Learn to code for free with millions of people.','JavaScript','425k'],['microsoft/vscode','Visual Studio Code editor.','TypeScript','168k'],['vercel/next.js','The React Framework for the Web.','JavaScript','132k'],['ohmyzsh/ohmyzsh','A delightful community-driven framework.','Shell','180k'],['tailwindlabs/tailwindcss','A utility-first CSS framework.','CSS','91k'],['public-apis/public-apis','A collective list of free APIs.','Python','390k']].filter(x=>!state.exploreSearch||x.join(' ').toLowerCase().includes(state.exploreSearch.toLowerCase()));const cards=projects.map(x=>`<article class="repo-discovery"><div><span class="repo-icon">▤</span><button class="text-link" data-action="open-repo"><b>${x[0]}</b></button><span class="tag">Public</span></div><p>${x[1]}</p><small>● ${x[2]}　☆ ${x[3]} stars</small><div class="annotated-control"><button class="button" data-action="star-project">☆ Star</button><small>收藏项目，稍后可在个人主页找到</small></div><div class="annotated-control"><button class="button subtle" data-action="view-project">View repository</button><small>打开这个示例项目的仓库页面</small></div></article>`).join('');main.innerHTML=`<div class="content-header"><div class="eyebrow">DISCOVER PROJECTS</div><h1>Explore</h1><p>Browse public projects and learn how GitHub discovery works. Examples here are simulated.</p></div><div class="explore-tabs"><button class="filter-chip active" data-action="explore-tab" data-value="For you">For you</button><button class="filter-chip" data-action="explore-tab" data-value="Trending">Trending</button><button class="filter-chip" data-action="explore-tab" data-value="Topics">Topics</button><button class="filter-chip" data-action="explore-tab" data-value="Collections">Collections</button></div><div class="explore-search"><input class="inline-input" id="project-search" placeholder="Search repositories by name or topic…" value="${esc(state.exploreSearch||'')}"><button class="button primary" data-action="explore-search">Search</button></div><div class="section-head"><div><h2>${esc(state.exploreTab||'For you')} repositories</h2><p>英文按钮下方附有中文用途注释。</p></div></div><div class="cards">${cards||'<div class="empty">No repositories match your search.</div>'}</div>`}
function dictionary(){const rows=vocab.filter(v=>(!state.search||v.join(' ').toLowerCase().includes(state.search.toLowerCase()))&&(state.dictFilter==='全部'||v[4]===state.dictFilter));main.innerHTML=`<div class="content-header"><div class="eyebrow">随时查 · 英文对照中文</div><h1>GitHub 英文词汇表</h1><p>保留英文原词，帮助你认出真实 GitHub 上的页面和按钮。</p></div><div class="filter-row">${['全部','页面','操作','协作','团队'].map(x=>`<button class="filter-chip ${state.dictFilter===x?'active':''}" data-action="dict-filter" data-value="${x}">${x}</button>`).join('')}</div><div class="word-grid">${rows.map(v=>`<article class="word-card" tabindex="0" data-explain="${esc(v[0])}"><b>${esc(v[0])}</b><span>${esc(v[1])}</span><p>${esc(v[2])} · 常见于：${esc(v[3])}</p></article>`).join('')||'<div class="empty">没有找到相关词。试试其他关键词。</div>'}</div>`}
function quiz(){const qs=[['“New repository” 通常用来做什么？',['新建项目仓库','关注仓库','查看历史'],0],['“Issues” 页面主要做什么？',['发布软件包','记录问题和待办','切换头像'],1],['“Pull request” 用来做什么？',['提出修改供审查和合并','下载网站','创建账号'],0],['“Actions” 常用来做什么？',['管理关注者','运行自动化流程','编辑个人资料'],1]];main.innerHTML=`<div class="content-header"><div class="eyebrow">随时查 · 检查理解</div><h1>英文按钮小测验</h1><p>选择答案后会显示解释，答错也没关系。</p></div><section class="panel" style="max-width:760px"><div class="panel-title">快速练习 <small>4 道题</small></div><div class="panel-body">${qs.map((q,i)=>`<div class="quiz-q" data-answer="${q[2]}" data-id="q${i}"><b>${i+1}. ${q[0]}</b>${q[1].map((o,j)=>`<button class="quiz-option" data-q="${i}" data-option="${j}">${o}</button>`).join('')}<p class="quiz-feedback"></p></div>`).join('')}<button class="button primary" data-action="finish-quiz">完成测验</button> <button class="button" data-action="reset-quiz">重新开始</button></div></section>`}
function explain(name,override){state.selected=name;let v=vocab.find(x=>x[0].toLowerCase()===name.toLowerCase());let meaning=override||v?.[1]||({Notifications:'查看 GitHub 通知',Overview:'概览页面',People:'组织成员',Teams:'组织团队',Features:'仓库功能开关','Danger Zone':'高影响设置区域'}[name]||'打开此功能区并查看相关信息');let copy=v?.[2]||`这个英文通常出现在“${pageInfo[state.page]?.[0]||'GitHub'}”页面。了解它的意思后，就能更容易判断下一步。`;let panel=document.querySelector('#explain-content');if(panel)panel.innerHTML=`<h3 class="explain-word">${esc(name)}</h3><div class="explain-meaning">${esc(meaning)}</div><p class="explain-copy">${esc(copy)}</p><div class="explain-example">记忆提示：<b>${esc(name)}</b> → ${esc(meaning)}。遇到时先理解英文，再判断是否操作。</div>`;let node=document.querySelector('#explain-panel');if(node&&innerWidth<1000)node.scrollIntoView({behavior:'smooth',block:'nearest'});if(!panel)toast(name+'：'+meaning+'。'+copy)}
function hideOverlays(){document.querySelector('#search-overlay')?.remove();document.querySelector('#profile-menu')?.remove();document.querySelector('#create-menu')?.remove()}
function showSearchOverlay(){if(document.querySelector('#search-overlay'))return;document.querySelector('#profile-menu')?.remove();const html=`<div class="search-backdrop" id="search-overlay"><section class="search-dialog"><div class="search-input-row"><span>⌕</span><input id="overlay-search" placeholder="Search or jump to..." value="${esc(state.search||'')}"><kbd>ESC</kbd></div><div class="search-section-label">Repositories</div><div id="search-results"></div><div class="search-footer"><span>↑↓ to navigate</span><span>Enter to select</span><span>Esc to close</span></div></section></div>`;document.body.insertAdjacentHTML('beforeend',html);renderSearchResults(state.search||'');const input=document.querySelector('#overlay-search');input.focus();input.setSelectionRange(input.value.length,input.value.length);input.addEventListener('input',e=>{state.search=e.target.value;renderSearchResults(state.search)});input.addEventListener('keydown',e=>{if(e.key==='Escape'){hideOverlays();document.querySelector('#search').blur()}if(e.key==='Enter'){e.preventDefault();document.querySelector('#search-results [data-action]')?.click()}});document.querySelector('#search-overlay').addEventListener('click',e=>{if(e.target.id==='search-overlay')hideOverlays()})}
function renderSearchResults(q=''){const all=[['li-1116/wardrobe-miniprogram','Repository','search-open-repo'],['WangLaoShi/JobsCrawler','Repository','search-open-repo'],['octocat/Hello-World','Repository','search-open-repo'],['freeCodeCamp/freeCodeCamp','Repository','search-open-repo'],['octocat','User','search-open-profile'],['Explore repositories','Jump to','search-open-explore']];const rows=all.filter(x=>!q||x.join(' ').toLowerCase().includes(q.toLowerCase()));const host=document.querySelector('#search-results');if(host)host.innerHTML=rows.map(x=>`<button class="search-result" data-action="${x[2]}"><span class="search-result-icon">${x[1]==='User'?'◉':x[1]==='Jump to'?'⌕':'▤'}</span><span>${esc(x[0])}</span><small>${x[1]}</small><span class="search-jump">Jump to</span></button>`).join('')||'<div class="search-empty">No results found.</div>'}
function toggleUserMenu(){document.querySelector('#search-overlay')?.remove();document.querySelector('#create-menu')?.remove();if(document.querySelector('#profile-menu')){document.querySelector('#profile-menu').remove();return}const menu=`<div class="user-menu" id="profile-menu"><div class="user-menu-head"><span class="avatar">学</span><b>li-1116</b><button data-action="menu-switch">⇄</button></div><button class="user-menu-item" data-action="menu-status">☻　Set status</button><hr>${[['Profile','◉'],['Repositories','▤'],['Stars','☆'],['Gists','▣'],['Organizations','♧'],['Enterprises','◎'],['Sponsors','♡']].map(x=>`<button class="user-menu-item" data-action="menu-nav" data-value="${x[0]}">${x[1]}　${x[0]}</button>`).join('')}<hr>${[['Settings','⚙'],['Copilot settings','♧'],['Feature preview','⚗'],['Appearance','◐'],['Accessibility','♿'],['Try Enterprise','↗']].map(x=>`<button class="user-menu-item" data-action="menu-nav" data-value="${x[0]}">${x[1]}　${x[0]}</button>`).join('')}<hr><button class="user-menu-item" data-action="menu-nav" data-value="Sign out">↪　Sign out</button></div>`;document.body.insertAdjacentHTML('beforeend',menu);document.addEventListener('click',outsideMenu,{once:true})}
function outsideMenu(e){if(e.target.closest('#profile-menu')||e.target.closest('.avatar')){document.addEventListener('click',outsideMenu,{once:true});return}document.querySelector('#profile-menu')?.remove()}
function toggleCreateMenu(){if(document.querySelector('#create-menu')){document.querySelector('#create-menu').remove();return}document.querySelector('#profile-menu')?.remove();document.querySelector('#create-menu')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="create-menu" id="create-menu"><b>Create</b>${[['New repository','repo'],['Import repository','repo'],['New issue','issues'],['New organization','org']].map(x=>`<button class="user-menu-item" data-action="menu-nav" data-value="${x[1]}">＋　${x[0]}</button>`).join('')}</div>`)}
function act(a,val,el){switch(a){case'tab':if(state.page==='profile'){state.profileTab=val;render()}else if(state.page==='org'){state.orgTab=val;render()}else if(state.page==='settings'){state.settingsTab=val;render()}else if(state.page==='pulls'&&state.prDetail){state.prTab=val;render()}else{tabNav(val)}break;case'branch-menu':state.branchMenu=!state.branchMenu;state.fileMenu=false;render();break;case'switch-branch':state.branch=val;state.branchMenu=false;render();toast(`已切换到 ${val}`);break;case'create-branch':{let n=document.querySelector('#branch-name')?.value.trim();if(!n){toast('先输入新分支名称');break}if(!state.branches.includes(n))state.branches.push(n);state.branch=n;state.branchMenu=false;render();toast(`已创建并切换到 ${n}`);break}case'code-menu':state.codeOpen=!state.codeOpen;state.fileMenu=false;render();break;case'clone-type':state.cloneType=val;render();break;case'copy-clone':{let text=state.cloneType==='HTTPS'?'https://github.com/octocat/hello-world.git':state.cloneType==='SSH'?'git@github.com:octocat/hello-world.git':'gh repo clone octocat/hello-world';navigator.clipboard?.writeText(text).then(()=>toast('克隆地址已复制')).catch(()=>toast(text));break}case'add-file':state.fileMenu=!state.fileMenu;render();break;case'create-file':state.fileMenu=false;state.fileComposer=true;render();break;case'cancel-file':state.fileComposer=false;render();break;case'save-file':{let name=document.querySelector('#new-filename')?.value.trim(),content=document.querySelector('#new-filecontent')?.value||'';if(!name){toast('请输入文件名');break}state.files.unshift({name,message:`Create ${name}`,time:'just now',content});state.fileComposer=false;render();toast(`${name} 已添加到演示仓库`);break}case'open-file':state.fileOpen=val;render();break;case'back-files':state.fileOpen='';render();break;case'edit-file':toast('Edit：在真实 GitHub 中开始编辑当前文件；此处演示按钮用途');break;case'edit-readme':state.fileOpen='README.md';render();break;case'goto-file':state.gotoOpen=!state.gotoOpen;render();break;case'close-goto':state.queryFile='';state.gotoOpen=false;render();break;case'global-search':document.querySelector('#search').focus();break;case'create-menu':toggleCreateMenu();break;case'explore':nav('explore');break;case'feed':nav('feed');break;case'feed-filter-toggle':state.feedDropdown=!state.feedDropdown;render();break;case'feed-filter-set':state.feedFilter=val;state.feedDropdown=false;render();break;case'feed-react':state.feedReacted=!state.feedReacted;render();toast(state.feedReacted?'已添加反应':'已取消反应');break;case'feed-post-menu':toast('动态更多选项：复制链接、隐藏此动态（模拟）');break;case'feed-expand':state.feedExpanded=!state.feedExpanded;render();break;case'search-open-repo':hideOverlays();nav('repo');break;case'search-open-explore':state.exploreSearch=state.search||'';hideOverlays();nav('explore');break;case'search-open-profile':hideOverlays();nav('profile');break;case'menu-nav':hideOverlays();if(val==='repo'){nav('repo')}else if(val==='issues'){nav('issues')}else if(val==='org'){nav('org')}else if(val==='Repositories'){state.profileTab='Repositories';nav('profile')}else if(val==='Stars'){state.profileTab='Stars';nav('profile')}else if(val==='Organizations'){nav('org')}else if(val==='Settings'){nav('settings')}else if(val==='Profile'){nav('profile')}else{toast(val==='Sign out'?'演示账号保持登录状态，学习站不会退出真实 GitHub':'此功能在 GitHub 中用于'+val+'；当前演示提供中文说明')}break;case'menu-switch':toast('账号切换菜单（演示）');break;case'menu-status':toast('状态设置：可以设置当前工作状态（模拟）');break;case'dismiss-banner':document.querySelector('#education-banner')?.remove();break;case'explore-tab':state.exploreTab=val;render();break;case'explore-search':state.exploreSearch=document.querySelector('#project-search')?.value.trim()||'';render();break;case'star-project':toast('已收藏这个演示项目');break;case'view-project':nav('repo');break;case'home-customize':toast('首页布局设置（演示）');break;case'feed-filter':toast('动态筛选（演示）');break;case'feed-more':toast('已显示最新动态');break;case'repo-new':toast('新建仓库练习请从仓库与代码课程开始');break;case'all-repos':nav('profile');state.profileTab='Repositories';render();break;case'learn':nav('overview');break;case'star':state.starred=!state.starred;render();toast(state.starred?'已收藏示例仓库':'已取消收藏');break;case'watch':state.watching=!state.watching;render();toast(state.watching?'已关注示例仓库':'已取消关注');break;case'fork':state.forked=!state.forked;render();toast(state.forked?'已创建演示派生副本':'已取消演示派生');break;case'new-issue':state.issueComposer=true;render();break;case'cancel-issue':state.issueComposer=false;render();break;case'save-issue':{let title=document.querySelector('#issue-title')?.value.trim();if(!title){toast('请先填写标题');break}let id=Math.max(0,...state.issues.map(x=>x.id))+1;state.issues.unshift({id,title,label:'enhancement',open:true});state.issueComposer=false;complete('issues');render();toast(`Issue #${id} 已创建`);break}case'issue-filter':state.issueFilter=val;state.issueDetail=null;render();break;case'issue-detail':state.issueDetail=Number(val);render();break;case'issue-back':state.issueDetail=null;render();break;case'toggle-issue':{let i=state.issues.find(x=>x.id===state.issueDetail);if(i)i.open=!i.open;render();toast(i?.open?'已重新打开 Issue':'Issue 已关闭');break}case'label-menu':state.labelMenu=!state.labelMenu;state.milestoneMenu=false;render();break;case'milestone-menu':state.milestoneMenu=!state.milestoneMenu;state.labelMenu=false;render();break;case'filter-label':state.issues=state.issues.filter(i=>i.label===val);state.labelMenu=false;render();toast(`已按 ${val} 筛选`);break;case'milestone-create':toast('已打开里程碑创建演示');break;case'new-pr':state.prComposer=true;state.prDetail=false;render();break;case'cancel-pr':state.prComposer=false;render();break;case'save-pr':{state.prTitle=document.querySelector('#pr-title')?.value.trim()||'Practice: improve README';state.prComposer=false;state.prDetail=true;state.prOpen=true;state.prMerged=false;complete('pulls');render();toast('Pull request 已创建');break}case'pr-detail':state.prDetail=true;state.prTab='Conversation';render();break;case'pr-back':state.prDetail=false;render();break;case'pr-tab':state.prTab=val;render();break;case'merge-pr':state.prMerged=true;state.prDetail=true;render();toast('Pull request 已合并到演示分支');break;case'close-pr':state.prOpen=false;state.prDetail=false;render();toast('Pull request 已关闭');break;case'run-workflow':state.actions++;complete('actions');render();toast('演示工作流运行成功');break;case'workflow-logs':state.logs=val;render();break;case'close-logs':state.logs=false;render();break;case'project-view':state.projectView=val;render();break;case'add-card':state.cardComposer=true;render();break;case'cancel-card':state.cardComposer=false;render();break;case'save-card':{let title=document.querySelector('#card-title')?.value.trim();if(!title){toast('请输入任务名称');break}state.cards.unshift({title,status:'Todo'});state.cardComposer=false;complete('projects');render();toast('任务已加入 Todo');break}case'move-card':{let card=state.cards.find(x=>x.title===val);if(card){card.status=el.value;render();toast(`已移动到 ${el.value}`)}break}case'card-detail':explain(val,'项目任务卡。可以查看内容并调整状态。');break;case'profile-edit':state.profileEditing=true;render();break;case'profile-cancel':state.profileEditing=false;render();break;case'profile-save':state.profileEditing=false;render();toast('个人资料已在演示中保存');break;case'profile-tab':state.profileTab=val;render();break;case'open-repo':nav('repo');break;case'repo-owner':nav('profile');break;case'assign-issue':state.issueAssigned=!state.issueAssigned;render();toast(state.issueAssigned?'已将此 Issue 分配给你':'已取消负责人分配');break;case'comment-issue':state.issueCommenting=true;render();break;case'post-comment':{let comment=document.querySelector('#issue-comment')?.value.trim();if(!comment){toast('请先输入评论内容');break}state.issueComments.push(comment);state.issueCommenting=false;render();toast('评论已添加到模拟讨论');break}case'cancel-comment':state.issueCommenting=false;render();break;case'open-profile':nav('profile');break;case'org-tab':state.orgTab=val;render();break;case'org-detail':state.orgDetail=val;render();break;case'org-clear':state.orgDetail='';render();break;case'settings-tab':state.settingsTab=val;render();break;case'rename':state.settingsForm=true;render();break;case'save-rename':{let name=document.querySelector('#repo-name')?.value.trim();if(!name){toast('仓库名称不能为空');break}state.settingsName=name;state.settingsForm=false;render();toast('示例仓库名称已更新');break}case'cancel-rename':state.settingsForm=false;render();break;case'features':state.featurePanel='Repository features';render();break;case'close-feature':state.featurePanel='';render();break;case'settings-detail':state.featurePanel=state.settingsTab;render();break;case'package-filter':state.packageType=el.value;render();break;case'package-detail':state.packageDetail=val;render();break;case'package-install':state.packageDetail='Install @octocat/'+val;render();break;case'package-close':state.packageDetail='';render();break;case'dict-filter':state.dictFilter=val;render();break;case'finish-quiz':{let score=[...document.querySelectorAll('.quiz-q')].filter(q=>q.dataset.done==='true'&&q.dataset.correct==='true').length;complete('quiz');toast(`测验完成：答对 ${score}/4 题`);break}case'reset-quiz':render();break;case'wiki-edit':explain('Wiki','创建项目文档页面');break;case'security-check':explain('Security','查看项目安全设置');break;case'insights-view':explain('Insights','查看项目活动数据');break;case'topics':explain('About','编辑仓库介绍和主题标签');break;case'releases':explain('Releases','查看项目发布版本');break;case'packages-nav':nav('packages');break;case'contributors':explain('Contributors','查看参与项目的贡献者');break;case'edit-readme':state.fileOpen='README.md';render();break;default:explain(val||a)}}
document.querySelector('.sidebar').addEventListener('click',e=>{const n=e.target.closest('[data-page],[data-action]');if(n){e.preventDefault();if(n.dataset.page){complete(n.dataset.page);nav(n.dataset.page)}else act(n.dataset.action,n.dataset.value,n)}});
main.addEventListener('click',e=>{let n=e.target.closest('[data-nav]');if(n){complete(n.dataset.nav);nav(n.dataset.nav);return}let a=e.target.closest('[data-action]');if(a){if(a.matches('select'))return;act(a.dataset.action,a.dataset.value,a);return}let ex=e.target.closest('[data-explain]');if(ex){explain(ex.dataset.explain,ex.dataset.meaning);return}let opt=e.target.closest('.quiz-option');if(opt){let q=document.querySelector(`.quiz-q[data-id="q${opt.dataset.q}"]`);if(!q||q.dataset.done)return;let right=Number(q.dataset.answer)===Number(opt.dataset.option);q.dataset.done='true';q.dataset.correct=String(right);opt.classList.add(right?'correct':'wrong');q.querySelectorAll('.quiz-option')[Number(q.dataset.answer)].classList.add('correct');q.querySelector('.quiz-feedback').textContent=right?'答对了！':'再记一下这个词的意思。';return}});
main.addEventListener('change',e=>{if(e.target.matches('#upload-file')&&e.target.files[0]){let f=e.target.files[0];state.files.unshift({name:f.name,message:'Upload files',time:'just now',content:'Uploaded file shown for simulation.'});state.fileMenu=false;render();toast(`${f.name} 已加入演示列表`)}if(e.target.id==='file-search'){state.queryFile=e.target.value;render();document.querySelector('#file-search')?.focus()}if(e.target.matches('[data-action="move-card"]'))act('move-card',e.target.dataset.value,e);if(e.target.matches('[data-action="package-filter"]')){state.packageType=e.target.value;render()}});
main.addEventListener('input',e=>{if(e.target.id==='file-search'){state.queryFile=e.target.value;let pos=e.target.selectionStart;render();let input=document.querySelector('#file-search');input?.focus();input?.setSelectionRange(pos,pos)}});
main.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-nav],[data-explain],[data-action]')){e.preventDefault();e.target.click()}});
document.querySelector('#search').addEventListener('focus',showSearchOverlay);document.querySelector('#search').addEventListener('click',showSearchOverlay);document.querySelector('#search').addEventListener('input',e=>{state.search=e.target.value.trim();if(state.page==='dictionary')dictionary();if(document.querySelector('#search-overlay'))renderSearchResults(state.search)});document.querySelector('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=document.querySelector('#search-overlay [data-action]');if(first)first.click();else{hideOverlays();nav('explore')}}});document.querySelector('#help')?.addEventListener('click',()=>toast('点英文控件查看解释；练习不会连接真实 GitHub。'));document.addEventListener('keydown',e=>{if(e.key==='/'&&!document.activeElement.matches('input,textarea,select,[contenteditable]')){e.preventDefault();document.querySelector('#search').focus()}if(e.key==='Escape'){document.querySelector('#search').blur();hideOverlays()}});render();

function annotateButtons(){const byAction={"tab":v=>({Code:'查看仓库文件和代码',Issues:'查看、创建和跟踪问题任务','Pull requests':'审查并合并代码修改',Actions:'查看自动化工作流',Projects:'整理项目任务',Wiki:'查看项目文档',Security:'检查项目安全状态',Insights:'查看项目数据和活动',Settings:'管理仓库设置',Overview:'查看个人主页概览',Repositories:'查看此用户的项目仓库',Projects:'查看此用户参与的项目',Packages:'查看此用户发布的软件包',Stars:'查看此用户收藏的项目',People:'查看组织成员',Teams:'查看组织团队',General:'查看常规设置',Access:'管理访问权限',Branches:'查看分支规则',Webhooks:'管理事件通知集成','Danger Zone':'查看高影响设置'}[v]||'切换到此功能页面'),"branch-menu":'切换分支或创建新分支',"switch-branch":'切换到这个代码分支',"create-branch":'创建一个新的代码分支',"code-menu":'打开克隆和下载选项',"clone-type":v=>`选择 ${v} 方式获取项目地址`,"copy-clone":'复制仓库地址，用于 GitHub Desktop 克隆',"add-file":'新建文件或上传已有文件',"create-file":'开始创建仓库文件',"save-file":'保存文件并记录一次提交',"goto-file":'按文件名查找仓库中的文件',"open-file":'打开并查看这个文件',"edit-file":'编辑当前文件内容',"star":'收藏或取消收藏此仓库',"watch":'关注或取消关注仓库动态',"fork":'在自己的账号下复制此仓库',"new-issue":'新建一个问题、建议或待办任务',"save-issue":'提交并创建这条 Issue',"issue-filter":v=>v==='open'?'只查看尚未解决的问题':'查看已经关闭的问题',"issue-detail":'打开 Issue 详情和讨论',"toggle-issue":'关闭已解决的问题，或重新打开它',"label-menu":'按标签分类和筛选 Issues',"milestone-menu":'按版本或阶段整理 Issues',"new-pr":'发起代码修改审查请求',"save-pr":'创建 Pull request 并请求审查',"pr-detail":'打开 Pull request 详情',"merge-pr":'把审查通过的修改合并到目标分支',"close-pr":'关闭这条 Pull request',"run-workflow":'手动运行一次自动化工作流',"workflow-logs":'查看工作流运行步骤和日志',"project-view":v=>v==='Board'?'按状态看板查看任务':'用表格查看任务字段',"add-card":'向项目中添加一条任务',"save-card":'保存任务并加入 Todo 列',"move-card":'更改任务当前所处状态',"profile-edit":'编辑个人主页资料',"profile-save":'保存个人资料修改',"rename":'修改仓库名称',"features":'管理仓库启用的功能',"package-filter":'按软件包类型筛选列表',"package-detail":'查看软件包发布版本',"package-install":'查看如何安装或引用软件包',"dict-filter":v=>`只显示“${v}”类英文词汇`,"explore-tab":v=>`浏览 ${v} 类型的公开项目`,"explore-search":'按名称或主题搜索公开仓库',"star-project":'收藏这个公开项目',"view-project":'打开这个项目的仓库页面',"feed-filter":'筛选首页动态内容',"feed-more":'继续查看更早的动态',"all-repos":'查看个人主页中的全部仓库',"explore":'浏览和发现公开项目',"global-search":'搜索 GitHub 页面、仓库和用户',"open-repo":'打开这个仓库的文件和协作页面',"open-profile":'查看用户个人主页',"assign-issue":'将 Issue 分配给自己或取消分配',"comment-issue":'在 Issue 讨论中添加评论',"post-comment":'发布这条评论',"repo-owner":'打开仓库所有者的个人主页',"create-menu":'打开快捷创建菜单','feed-filter-toggle':'筛选 Feed 动态内容','feed-filter-set':v=>'只显示'+v+'类型的动态','feed-react':'对这条动态添加或取消表情回应','feed-post-menu':'打开这条动态的更多选项','feed-expand':'展开更多或收起动态','search-open-repo':'打开搜索结果中的仓库','search-open-profile':'打开用户个人主页','search-open-explore':'搜索并浏览公开项目','menu-nav':v=>'打开账户菜单中的'+v+'页面','menu-status':'设置个人状态','menu-switch':'切换账号','create-menu':'打开快捷创建菜单','dismiss-banner':'关闭这条公告','repo-owner':'打开仓库所有者主页'};const labels={"Search or jump to...":'搜索仓库、用户和 GitHub 功能',"Notifications":'查看 GitHub 通知',"New issue":'新建问题或任务',"Labels ▾":'按标签筛选问题',"Milestones ▾":'按里程碑筛选问题',"2 Open":'查看尚未解决的问题',"0 Closed":'查看已经关闭的问题',"New pull request":'发起代码修改审查请求',"Run workflow":'手动运行自动化任务',"Add item":'向项目添加任务',"Edit profile":'编辑个人主页资料',"Create new file":'创建一个新文件',"Upload files":'上传已有文件',"Go to file":'按名称查找仓库文件',"Add file ▾":'新建或上传文件',"Code ▾":'查看克隆和下载选项',"Fork":'在自己的账号下复制此仓库',"Star":'收藏此仓库',"Watch":'关注仓库动态',"View repository":'打开项目仓库'};document.querySelectorAll('.sim-panel button,.gh-home button,.feed-column button,.repo-discovery button,.top-actions .header-icon').forEach(b=>{if(b.matches('.practice-help'))return;const label=(b.innerText||b.getAttribute('aria-label')||'').replace(/\s+/g,' ').trim();let note=b.dataset.action?(typeof byAction[b.dataset.action]==='function'?byAction[b.dataset.action](b.dataset.value):byAction[b.dataset.action]):null;note=note||labels[label]||b.dataset.note||'点击后查看此英文控件对应的页面或内容';let wrap=b.parentElement?.classList.contains('button-unit')?b.parentElement:null;if(!wrap){wrap=document.createElement('span');wrap.className='button-unit';b.before(wrap);wrap.append(b)}let n=wrap.querySelector('.button-annotation');if(!n){n=document.createElement('small');n.className='button-annotation';wrap.append(n)}if(n.textContent!==note)n.textContent=note})}
document.body.addEventListener('click',e=>{const b=e.target.closest('#search-overlay [data-action],#profile-menu [data-action],#create-menu [data-action]');if(b)act(b.dataset.action,b.dataset.value,b)});annotateButtons();new MutationObserver(annotateButtons).observe(main,{childList:true,subtree:true});
document.querySelector('.avatar')?.addEventListener('click',toggleUserMenu);document.querySelector('.top-actions')?.addEventListener('click',e=>{const b=e.target.closest('[data-page],[data-action]');if(!b)return;if(b.dataset.page)nav(b.dataset.page);else act(b.dataset.action,b.dataset.value,b)});document.querySelector('.side-search')?.addEventListener('click',()=>document.querySelector('#search').focus());




const navToggle = document.querySelector('.menu-toggle');
const navDrawer = document.querySelector('#site-navigation');
navToggle.addEventListener('click', () => {
  navDrawer.showModal();
  navToggle.setAttribute('aria-expanded', 'true');
});
navDrawer.addEventListener('close', () => {
  navToggle.setAttribute('aria-expanded', 'false');
  navToggle.focus();
});
navDrawer.addEventListener('click', event => {
  if (event.target === navDrawer || event.target.closest('a[href], [data-page], [data-action="open-repo"]')) {
    navDrawer.close();
  }
});

